INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0006-000000000001', 'b0000001-0000-0000-0000-000000000006', 'b0000000-0000-0000-0000-000000000001', 1, 'las-habitaciones-de-la-casa', '{"es": "Las Habitaciones de la Casa", "en": "The Rooms of the House"}'::jsonb, '{"es": "Aprende el vocabulario de las habitaciones de una casa y usa there is/are para describir tu hogar.", "en": "Learn vocabulary for the rooms of a house and use there is/are to describe your home."}'::jsonb, 'vocabulary', 20, 12, '{"intro": "En esta lección vas a aprender el vocabulario de las habitaciones de una casa en inglés, y a usar ''there is'' y ''there are'' (que ya conoces) para describir tu hogar.", "sections": [{"type": "table", "title": "HABITACIONES DE LA CASA", "headers": ["Inglés", "Español"], "rows": [["kitchen", "cocina"], ["bedroom", "dormitorio"], ["bathroom", "baño"], ["living room", "sala de estar / salón"], ["dining room", "comedor"], ["garage", "garaje"], ["garden", "jardín"], ["hallway", "pasillo"]]}, {"type": "explanation", "title": "THERE IS / THERE ARE PARA DESCRIBIR LA CASA", "text": "Ya conoces ''there is'' (singular) y ''there are'' (plural) para decir que algo existe. Los usamos también para describir qué habitaciones hay en una casa: ''There is a kitchen'' (singular) y ''There are three bedrooms'' (plural). Para el negativo: ''There isn''t a garage'' o ''There aren''t any bedrooms downstairs.''"}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "There is a kitchen and a living room.", "es": "Hay una cocina y una sala de estar."}, {"en": "There are three bedrooms in my house.", "es": "Hay tres dormitorios en mi casa."}, {"en": "There is a garden behind the house.", "es": "Hay un jardín detrás de la casa."}, {"en": "There isn''t a garage in my apartment.", "es": "No hay garaje en mi apartamento."}]}, {"type": "note", "variant": "info", "text": "En inglés británico se dice ''garden'', pero en inglés americano se usa a menudo ''yard'' para el jardín trasero. Con el tiempo aprenderás ambas variantes."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0001-0006-0001-000000000001', 'b0000002-0000-0000-0006-000000000001', 1, 'flashcard', '{"text": "kitchen"}'::jsonb, '{"text": "la cocina", "phonetic": "/ˈkɪtʃɪn/"}'::jsonb, NULL, NULL, '{"vocab:house_rooms"}'),
('b0000003-0001-0006-0002-000000000001', 'b0000002-0000-0000-0006-000000000001', 2, 'flashcard', '{"text": "bedroom"}'::jsonb, '{"text": "el dormitorio", "phonetic": "/ˈbedruːm/"}'::jsonb, NULL, NULL, '{"vocab:house_rooms"}'),
('b0000003-0001-0006-0003-000000000001', 'b0000002-0000-0000-0006-000000000001', 3, 'flashcard', '{"text": "bathroom"}'::jsonb, '{"text": "el baño", "phonetic": "/ˈbæθruːm/"}'::jsonb, NULL, NULL, '{"vocab:house_rooms"}'),
('b0000003-0001-0006-0004-000000000001', 'b0000002-0000-0000-0006-000000000001', 4, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "living room", "es": "sala de estar"}, {"en": "dining room", "es": "comedor"}, {"en": "garage", "es": "garaje"}, {"en": "hallway", "es": "pasillo"}]}'::jsonb, NULL, NULL, '{"vocab:house_rooms"}'),
('b0000003-0001-0006-0005-000000000001', 'b0000002-0000-0000-0006-000000000001', 5, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "kitchen", "es": "la cocina"}, {"en": "bedroom", "es": "el dormitorio"}, {"en": "bathroom", "es": "el baño"}, {"en": "garden", "es": "el jardín"}]}'::jsonb, NULL, NULL, '{"vocab:house_rooms"}'),
('b0000003-0001-0006-0006-000000000001', 'b0000002-0000-0000-0006-000000000001', 6, 'multiple_choice', '{"text": "Where do you cook food?"}'::jsonb, '{"text": "kitchen"}'::jsonb, '["bathroom", "garage", "bedroom"]'::jsonb, '{"es": "La cocina (kitchen) es la habitación donde preparamos y cocinamos la comida."}'::jsonb, '{"vocab:house_rooms"}'),
('b0000003-0001-0006-0007-000000000001', 'b0000002-0000-0000-0006-000000000001', 7, 'fill_blank', '{"text": "There ___ a garden behind my house."}'::jsonb, '{"text": "is", "accepted": ["is"]}'::jsonb, NULL, '{"es": "Con ''a garden'' (singular) usamos ''there is''."}'::jsonb, '{"grammar:there_is_are","vocab:house_rooms"}'),
('b0000003-0001-0006-0008-000000000001', 'b0000002-0000-0000-0006-000000000001', 8, 'fill_blank', '{"text": "There are three ___ in my house."}'::jsonb, '{"text": "bedrooms", "accepted": ["bedrooms"]}'::jsonb, NULL, NULL, '{"vocab:house_rooms"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0006-000000000002', 'b0000001-0000-0000-0000-000000000006', 'b0000000-0000-0000-0000-000000000001', 2, 'los-muebles', '{"es": "Los Muebles", "en": "Furniture"}'::jsonb, '{"es": "Aprende el vocabulario de los muebles más comunes y combínalo con las habitaciones de la casa.", "en": "Learn vocabulary for common furniture and combine it with the rooms of the house."}'::jsonb, 'vocabulary', 20, 12, '{"intro": "Ahora que conoces las habitaciones, vas a aprender el vocabulario de los muebles más comunes y a combinarlos con las habitaciones usando ''there is/are''.", "sections": [{"type": "table", "title": "MUEBLES DE LA CASA", "headers": ["Inglés", "Español"], "rows": [["bed", "cama"], ["sofa / couch", "sofá"], ["table", "mesa"], ["chair", "silla"], ["wardrobe / closet", "armario"], ["fridge", "frigorífico / nevera"], ["shelf", "estantería"], ["lamp", "lámpara"], ["desk", "escritorio"], ["mirror", "espejo"]]}, {"type": "explanation", "title": "MUEBLES Y HABITACIONES", "text": "Podemos combinar el vocabulario de muebles con el de habitaciones usando ''there is'' y ''there are''. Por ejemplo: ''There is a bed in the bedroom'' o ''There are two chairs in the dining room''."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "There is a bed in the bedroom.", "es": "Hay una cama en el dormitorio."}, {"en": "There is a sofa in the living room.", "es": "Hay un sofá en la sala de estar."}, {"en": "There are two chairs in the dining room.", "es": "Hay dos sillas en el comedor."}, {"en": "There is a fridge in the kitchen.", "es": "Hay un frigorífico en la cocina."}]}, {"type": "note", "variant": "tip", "text": "''Sofa'' y ''couch'' significan lo mismo; ''wardrobe'' es más británico y ''closet'' más americano. Puedes usar cualquiera de los dos."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0002-0006-0001-000000000001', 'b0000002-0000-0000-0006-000000000002', 1, 'flashcard', '{"text": "bed"}'::jsonb, '{"text": "la cama", "phonetic": "/bed/"}'::jsonb, NULL, NULL, '{"vocab:furniture"}'),
('b0000003-0002-0006-0002-000000000001', 'b0000002-0000-0000-0006-000000000002', 2, 'flashcard', '{"text": "sofa"}'::jsonb, '{"text": "el sofá", "phonetic": "/ˈsoʊfə/"}'::jsonb, NULL, NULL, '{"vocab:furniture"}'),
('b0000003-0002-0006-0003-000000000001', 'b0000002-0000-0000-0006-000000000002', 3, 'flashcard', '{"text": "wardrobe"}'::jsonb, '{"text": "el armario", "phonetic": "/ˈwɔːrdroʊb/"}'::jsonb, NULL, NULL, '{"vocab:furniture"}'),
('b0000003-0002-0006-0004-000000000001', 'b0000002-0000-0000-0006-000000000002', 4, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "table", "es": "la mesa"}, {"en": "chair", "es": "la silla"}, {"en": "fridge", "es": "el frigorífico"}, {"en": "lamp", "es": "la lámpara"}]}'::jsonb, NULL, NULL, '{"vocab:furniture"}'),
('b0000003-0002-0006-0005-000000000001', 'b0000002-0000-0000-0006-000000000002', 5, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "shelf", "es": "la estantería"}, {"en": "desk", "es": "el escritorio"}, {"en": "mirror", "es": "el espejo"}, {"en": "sofa", "es": "el sofá"}]}'::jsonb, NULL, NULL, '{"vocab:furniture"}'),
('b0000003-0002-0006-0006-000000000001', 'b0000002-0000-0000-0006-000000000002', 6, 'multiple_choice', '{"text": "What piece of furniture do you sleep on?"}'::jsonb, '{"text": "bed"}'::jsonb, '["chair", "desk", "shelf"]'::jsonb, '{"es": "Dormimos en la cama (bed)."}'::jsonb, '{"vocab:furniture"}'),
('b0000003-0002-0006-0007-000000000001', 'b0000002-0000-0000-0006-000000000002', 7, 'fill_blank', '{"text": "There is a ___ in the kitchen to keep food cold."}'::jsonb, '{"text": "fridge", "accepted": ["fridge"]}'::jsonb, NULL, NULL, '{"vocab:furniture"}'),
('b0000003-0002-0006-0008-000000000001', 'b0000002-0000-0000-0006-000000000002', 8, 'fill_blank', '{"text": "There is a bed and a wardrobe in the ___."}'::jsonb, '{"text": "bedroom", "accepted": ["bedroom"]}'::jsonb, NULL, NULL, '{"vocab:house_rooms","vocab:furniture"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0006-000000000003', 'b0000001-0000-0000-0000-000000000006', 'b0000000-0000-0000-0000-000000000001', 3, 'preposiciones-de-lugar', '{"es": "Preposiciones de Lugar", "en": "Prepositions of Place"}'::jsonb, '{"es": "Aprende a usar in, on, under, next to, between, in front of y behind para describir dónde están las cosas.", "en": "Learn to use in, on, under, next to, between, in front of, and behind to describe where things are."}'::jsonb, 'grammar', 22, 14, '{"intro": "Las preposiciones de lugar indican dónde están las cosas. En esta lección vas a aprender las preposiciones más comunes en inglés para describir la posición de objetos y muebles en la casa.", "sections": [{"type": "table", "title": "PREPOSICIONES DE LUGAR", "headers": ["Inglés", "Español", "Ejemplo"], "rows": [["in", "en / dentro de", "The book is in the bag."], ["on", "sobre / encima de", "The lamp is on the table."], ["under", "debajo de", "The shoes are under the bed."], ["next to", "al lado de", "The chair is next to the desk."], ["between", "entre", "The mirror is between the bed and the wardrobe."], ["in front of", "delante de", "The car is in front of the garage."], ["behind", "detrás de", "The garden is behind the house."]]}, {"type": "explanation", "title": "CÓMO SE USAN", "text": "Las preposiciones de lugar van antes del sustantivo y después del verbo ''to be''. La estructura es: sujeto + to be + preposición + lugar. Por ejemplo: ''The sofa is in the living room.'' No cambian de forma, son siempre iguales sin importar el sujeto."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "The fridge is in the kitchen.", "es": "El frigorífico está en la cocina."}, {"en": "The lamp is on the table.", "es": "La lámpara está sobre la mesa."}, {"en": "The shoes are under the bed.", "es": "Los zapatos están debajo de la cama."}, {"en": "The chair is next to the desk.", "es": "La silla está al lado del escritorio."}, {"en": "The mirror is between the bed and the wardrobe.", "es": "El espejo está entre la cama y el armario."}, {"en": "The car is in front of the garage.", "es": "El coche está delante del garaje."}, {"en": "The garden is behind the house.", "es": "El jardín está detrás de la casa."}]}, {"type": "note", "variant": "tip", "text": "Truco: ''next to'' e ''in front of'' siempre van juntas como una sola expresión — no olvides todas las palabras cuando las uses."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0003-0006-0001-000000000001', 'b0000002-0000-0000-0006-000000000003', 1, 'multiple_choice', '{"text": "The book is ___ the table."}'::jsonb, '{"text": "on"}'::jsonb, '["in", "under", "behind"]'::jsonb, '{"es": "Usamos ''on'' cuando algo está sobre una superficie."}'::jsonb, '{"grammar:prepositions_of_place"}'),
('b0000003-0003-0006-0002-000000000001', 'b0000002-0000-0000-0006-000000000003', 2, 'multiple_choice', '{"text": "The car is ___ the garage."}'::jsonb, '{"text": "in"}'::jsonb, '["on", "next to", "between"]'::jsonb, '{"es": "Usamos ''in'' cuando algo está dentro de un espacio cerrado."}'::jsonb, '{"grammar:prepositions_of_place"}'),
('b0000003-0003-0006-0003-000000000001', 'b0000002-0000-0000-0006-000000000003', 3, 'fill_blank', '{"text": "The shoes are ___ the bed."}'::jsonb, '{"text": "under", "accepted": ["under"]}'::jsonb, NULL, '{"es": "''Under'' significa debajo de."}'::jsonb, '{"grammar:prepositions_of_place"}'),
('b0000003-0003-0006-0004-000000000001', 'b0000002-0000-0000-0006-000000000003', 4, 'fill_blank', '{"text": "The lamp is ___ the desk."}'::jsonb, '{"text": "next to", "accepted": ["next to"]}'::jsonb, NULL, '{"es": "''Next to'' significa al lado de."}'::jsonb, '{"grammar:prepositions_of_place","vocab:furniture"}'),
('b0000003-0003-0006-0005-000000000001', 'b0000002-0000-0000-0006-000000000003', 5, 'translation', '{"text": "La silla está entre la mesa y el armario."}'::jsonb, '{"text": "The chair is between the table and the wardrobe.", "accepted": ["The chair is between the table and the wardrobe."]}'::jsonb, NULL, NULL, '{"grammar:prepositions_of_place"}'),
('b0000003-0003-0006-0006-000000000001', 'b0000002-0000-0000-0006-000000000003', 6, 'translation', '{"text": "El jardín está detrás de la casa."}'::jsonb, '{"text": "The garden is behind the house.", "accepted": ["The garden is behind the house."]}'::jsonb, NULL, NULL, '{"grammar:prepositions_of_place","vocab:house_rooms"}'),
('b0000003-0003-0006-0007-000000000001', 'b0000002-0000-0000-0006-000000000003', 7, 'word_bank_fill', '{"text": "The lamp is ___ the desk and the bed is ___ the wardrobe."}'::jsonb, '{"answers": ["on", "next to"]}'::jsonb, '["under", "behind"]'::jsonb, '{"es": "La lámpara está sobre (on) el escritorio y la cama está al lado de (next to) el armario."}'::jsonb, '{"grammar:prepositions_of_place"}'),
('b0000003-0003-0006-0008-000000000001', 'b0000002-0000-0000-0006-000000000003', 8, 'word_bank_fill', '{"text": "The mirror is ___ the wardrobe and the sofa is ___ the living room."}'::jsonb, '{"answers": ["behind", "in"]}'::jsonb, '["under", "between"]'::jsonb, '{"es": "El espejo está detrás de (behind) el armario y el sofá está en (in) la sala de estar."}'::jsonb, '{"grammar:prepositions_of_place","vocab:furniture"}');
